print("Input -> Output:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

# Let's see what changes occur
print("\nCharacter-by-character analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"'{inp}' -> '{outp}'")
    # Show differences
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        if j >= len(inp):
            print(f"  Position {j}: added '{outp[j]}'")
        elif j >= len(outp):
            print(f"  Position {j}: removed '{inp[j]}'")
        elif inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        else:
            print(f"  Position {j}: '{inp[j]}' unchanged")
    print()

